//! Rust source emission helpers. Generated files are written one table entry per line and their
//! `mod` declarations carry `#[rustfmt::skip]`, so the output is stable without running rustfmt.

use std::fmt::Write as _;

pub fn header(what: &str, sources: &[String]) -> String {
    let mut s = format!(
        "//! {what}\n//!\n//! @generated by `cargo run -p ghast-codegen-data` from PrismarineJS minecraft-data {} — do not edit.\n",
        crate::fetch::VERSION
    );
    if !sources.is_empty() {
        let _ = writeln!(s, "//! Sources: {}.", sources.join(", "));
    }
    s.push_str("\n#![allow(clippy::all, clippy::pedantic, clippy::nursery, missing_docs)]\n\n");
    s
}

pub fn lit(s: &str) -> String {
    format!("{s:?}")
}

pub fn f64l(x: f64) -> String {
    let s = format!("{x:?}");
    if s.contains('.') || s.contains('e') || s.contains("inf") || s.contains("NaN") {
        s
    } else {
        format!("{s}.0")
    }
}

pub fn f32l(x: f32) -> String {
    let s = format!("{x:?}");
    if s.contains('.') || s.contains('e') {
        s
    } else {
        format!("{s}.0")
    }
}

/// `oak_stairs` -> `OAK_STAIRS`; leading digits get a `_` prefix.
pub fn upper_ident(name: &str) -> String {
    let mut s: String = name
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect();
    if s.starts_with(|c: char| c.is_ascii_digit()) {
        s.insert(0, '_');
    }
    s
}

/// `has_bottle_0` -> `HasBottle0`.
pub fn camel_ident(name: &str) -> String {
    name.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|p| !p.is_empty())
        .map(|p| {
            let mut c = p.chars();
            c.next()
                .map(|f| f.to_ascii_uppercase().to_string() + c.as_str())
                .unwrap_or_default()
        })
        .collect()
}

/// A dense numeric table, `per_line` values per line.
pub fn num_table(out: &mut String, vis_name: &str, ty: &str, values: &[u32], per_line: usize) {
    let _ = writeln!(out, "{vis_name}: [{ty}; {}] = [", values.len());
    for chunk in values.chunks(per_line) {
        out.push_str("    ");
        for (i, v) in chunk.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            let _ = write!(out, "{v},");
        }
        out.push('\n');
    }
    out.push_str("];\n");
}

/// A name index sorted by name (byte order, as `str::cmp`).
pub fn name_index(out: &mut String, vis_name: &str, id_ty: &str, mut pairs: Vec<(String, u32)>) {
    pairs.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    pairs.dedup_by(|b, a| a.0 == b.0); // keep the first (lowest id) of duplicate names
    let _ = writeln!(out, "{vis_name}: [(&str, {id_ty}); {}] = [", pairs.len());
    for (n, id) in pairs {
        let _ = writeln!(out, "    ({}, {id}),", lit(&n));
    }
    out.push_str("];\n");
}
